const params=new URLSearchParams(location.search),$=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],names={昆明:'昆明',陇川:'陇川（瑞丽）',兰坪:'兰坪',凤庆:'凤庆'};const from=params.get('from')||'昆明',to=params.get('to')||'陇川',total=params.get('total')||'299';$('#route').textContent=`${names[from]||from} 至 ${names[to]||to}`;$('#flight').textContent=`${params.get('flight')||'JH1203'} · 运-12F`;$('#date').textContent=params.get('date')||'出发日期待定';$('#summary-total').textContent=total;$('#pay-total').textContent=total;let passenger={};try{passenger=JSON.parse(sessionStorage.getItem('yunxiang-passenger')||'{}')}catch{}$('#passenger').textContent=`${[passenger.surname,passenger.givenName].filter(Boolean).join(' ')||'乘机人 1'} · 成人`;
const amount=name=>Number(params.get(name))||0,fare=amount('price')||299,feeItems=[['基础票价',Math.max(0,fare-50)],['机场建设费',50],['燃油附加费',0]];if(params.get('seat'))feeItems.push([`座位 ${params.get('seat')}`,amount('seatPrice')]);if(amount('baggageExtra'))feeItems.push(['额外行李',amount('baggageExtra')]);if(amount('green'))feeItems.push(['乡途守护公益捐助',amount('green')]);if(amount('transport'))feeItems.push(['目的地接驳车',amount('transport')]);if(amount('insurance'))feeItems.push(['安心出行保险',amount('insurance')]);if(amount('hold'))feeItems.push(['票价保留',amount('hold')]);if(amount('discount'))feeItems.push(['优惠码',-amount('discount')]);$('#fee-detail').replaceChildren(...feeItems.map(([label,value])=>{const row=document.createElement('p');row.className=value<0?'discount':'';const name=document.createElement('span'),price=document.createElement('b');name.textContent=label;price.textContent=`${value<0?'−':''}¥${Math.abs(value)}`;row.append(name,price);return row}));
all('.order-row[type="button"]').forEach(row=>row.addEventListener('click',()=>{const detail=row.nextElementSibling,opening=detail.hidden;detail.hidden=!opening;row.querySelector('i').textContent=opening?'⌃':'⌄';row.setAttribute('aria-expanded',String(opening))}));
let method='校园卡',resultCopy='';const flow=$('#method-flow'),payButton=$('#pay-now'),payTotal=$('#pay-total'),payCaption=$('#pay-caption');
function lockPayment(){payButton.hidden=true;payTotal.textContent=total;payCaption.textContent='包括票价、税费和附加服务'}
function unlockPayment(label,copy,free=false){resultCopy=copy;payButton.textContent=label;payButton.hidden=false;if(free){payTotal.textContent='0';payCaption.textContent='耀天航空特别赠送 · 无需支付'}}
function renderFlow(){lockPayment();if(method==='校园卡'||method==='企业员工卡'){const campus=method==='校园卡',kind=campus?'学校':'企业';flow.innerHTML=`<form class="flow-form"><span>填写认证信息</span><h3>您所在的${kind}</h3><p>这里只用于本次趣味互动，不会验证或保存输入内容。</p><div><input id="organization" required autocomplete="off" placeholder="请输入${kind}名称"><button type="submit">确认</button></div></form>`;flow.querySelector('form').addEventListener('submit',event=>{event.preventDefault();const organization=$('#organization').value.trim();if(!organization)return;flow.innerHTML=`<div class="flow-success"><span>认证完成</span><h3>哇塞，竟然在 <strong id="organization-name"></strong> ${campus?'读书':'工作'}！</h3><p>${campus?'校长说给你报销了。愿你在校园里保持好奇，认真学习，也别忘了去看看更远的风景。':'你上级说帮你报销了。愿你的认真工作都被看见，也愿忙碌之外总有时间奔赴喜欢的地方。'}</p></div>`;$('#organization-name').textContent=organization;unlockPayment('领取免费机票',campus?'校长已经为您报销了这张虚拟机票。愿学业进步，每一次出发都遇见新的可能。':'您上级已经为您报销了这张虚拟机票。愿工作顺利，也愿生活里总有值得出发的远方。',true)})}else if(method==='未来的霉运'){flow.innerHTML='<div class="flow-form"><span>选择支付范围</span><h3>您愿意使用哪一段未来的霉运？</h3><div class="luck-options"><button type="button" data-luck="1">未来 1 年</button><button type="button" data-luck="10">未来 10 年</button><button type="button" data-luck="unknown">未来未知的霉运</button></div><p class="flow-message" id="flow-message">请选择一项。</p></div>';flow.querySelectorAll('[data-luck]').forEach(button=>button.addEventListener('click',()=>{flow.querySelectorAll('[data-luck]').forEach(item=>item.classList.toggle('selected',item===button));if(button.dataset.luck!=='unknown'){lockPayment();$('#flow-message').textContent='没有霉运哦！未来 1 年和 10 年的霉运余额都是零，请换一种方式。';return}$('#flow-message').textContent='未来未知的霉运已被清除。愿接下来的日子平安、顺利，偶尔的小意外也都能变成惊喜。';unlockPayment('用未知的霉运完成付款','未来未知的霉运已经被清除。愿您从此一路顺风，好运常在。')}))}else{flow.innerHTML='<div class="flow-form"><span>记忆整理</span><h3>放下一段不好的记忆</h3><p>不需要写下任何内容。点击后，我们只在这个虚拟页面里替您把它轻轻放下。</p><button class="memory-button" type="button">确认清除</button><p class="flow-message" id="flow-message"></p></div>';flow.querySelector('.memory-button').addEventListener('click',()=>{$('#flow-message').textContent='已经帮您清除了。请把更多目光留给眼前的道路与未来的风景，过去可以被记得，但不必一直背在身上。';unlockPayment('带着新的心情继续','不好的记忆已经被轻轻放下。请更多关注眼前的路与未来，愿新的旅程温柔明亮。')})}}
all('.method').forEach(button=>button.addEventListener('click',()=>{all('.method').forEach(item=>item.classList.toggle('selected',item===button));method=button.dataset.method;renderFlow()}));renderFlow();
const dialog=$('#result'),airportCodes={昆明:'KMG',陇川:'LCS',兰坪:'兰坪丰华通用机场',凤庆:'凤庆中和机场'};payButton.addEventListener('click',()=>{$('#result-title').textContent='支付成功 · 登机牌已生成';$('#result-copy').textContent=resultCopy;const fromCode=airportCodes[from]||from,toCode=airportCodes[to]||to;$('#bp-from').textContent=fromCode;$('#bp-to').textContent=toCode;$('#bp-from').classList.toggle('airport-name-code',fromCode.length>3);$('#bp-to').classList.toggle('airport-name-code',toCode.length>3);$('#bp-from-name').textContent=names[from]||from;$('#bp-to-name').textContent=names[to]||to;$('#bp-passenger').textContent=[passenger.surname,passenger.givenName].filter(Boolean).join(' ')||'乘机人 1';$('#bp-flight').textContent=params.get('flight')||'JH1203';$('#bp-date').textContent=params.get('date')||'待定';$('#bp-seat').textContent=params.get('seat')||'自动分配';const departure=({昆明:'07:00',陇川:'09:10',兰坪:'08:55',凤庆:'13:10'})[from]||'07:00',parts=departure.split(':').map(Number),minutes=(parts[0]*60+parts[1]-30+1440)%1440;$('#bp-time').textContent=`${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`;dialog.showModal()});$('.print-pass').addEventListener('click',()=>window.print());$('.result-finish').addEventListener('click',()=>{dialog.close();location.href='index.html'});
